/* From Uiverse.io by mnikita7767  - Tags: checkbox */
.__UIV_SCOPE__ .container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.__UIV_SCOPE__ .container label {
  cursor: pointer;
  position: relative;
  width: 80px;
  height: 80px;
  display: flex;
  justify-content: center;
  align-items: center;
}
.__UIV_SCOPE__ label input {
  appearance: none;
}
.__UIV_SCOPE__ label span {
  position: absolute;
  width: 100%;
  height: 100%;
  background: linear-gradient(#555353, #363535, #303030);
  border: 2px solid #222;
  border-top-width: 4px;
  border-radius: 6px;
  box-shadow: inset 0 5px 1px rgba(0, 0, 0, 0.23), 0 5px 5px rgba(0, 0, 0, 0.5),
    0 15px 25px rgba(0, 0, 0, 0.35);
}
.__UIV_SCOPE__ .container label span::before {
  content: "";
  position: absolute;
  border-top: 1px solid #fff;
  inset: 5px 3px;
  filter: blur(5px);
}
.__UIV_SCOPE__ .container label input:checked ~ span {
  box-shadow: inset 0 2px 2px rgba(0, 0, 0, 0.35),
    inset 0 5px 5px rgba(0, 0, 0, 0.5), inset 0 15px 25px rgba(0, 0, 0, 0.35);
}
.__UIV_SCOPE__ label p {
  position: relative;
  z-index: 10;
  font-size: 3rem;
  color: #111;
}
.__UIV_SCOPE__ .container label input:checked ~ p {
  color: #fff;
  text-shadow: 0 0 5px #219cf3, 0 0 8px #219cf3;
}
